    assert len(anc) == DL.N_ANCORAS_AESCALA == len(DL.ANCORAS_AESCALA) and set(anc) == {n_ for n_, a_ in fj["ancoras"].items() if a_["rel"] == rel}, "as ancoras da AEscala no delta nao sao as do FLAGS_v410.json"
